function nav(name,b){var aliases={accounts:"users",collections:"ledger",commission:"users",userWithdrawals:"ledger",merchantSettlement:"dashboard",merchantWithdrawals:"ledger",charges:"charges",frozen:"ledger",gpay:"users",history:"ledger",merchantGpay:"users",settlement:"dashboard",withdrawals:"ledger",usage:"ledger",earned:"dashboard",withdrawCommission:"dashboard"},target=aliases[name]||name;if(target==="charges")showChargesPage();document.querySelectorAll(".section").forEach(function(x){x.classList.remove("active")});var section=document.getElementById(target);if(section)section.classList.add("active");document.querySelectorAll(".nav button").forEach(function(x){x.classList.remove("active")});if(b)b.classList.add("active");var title=document.getElementById("title");if(title)title.textContent={dashboard:"Operations Dashboard",users:"Users / UPI Accounts",ledger:"Collections, Withdrawals and History",deposits:"Deposits",share:"Share Links",charges:"Merchant Charges"}[target]||name}
function showChargesPage(){var main=document.querySelector(".main");if(!main)return;var s=document.getElementById("charges");if(!s){s=document.createElement("section");s.id="charges";s.className="section";main.appendChild(s)}var rows=(db.merchantCharges||[]).map(function(c){return '<div class="entry"><div><b>'+money(c.amountInr)+'</b><div class="muted">'+dateFmt(c.date)+' · '+esc(c.reference||"No reference")+'</div></div><div><b>'+esc(c.userName)+'</b><div class="muted">'+esc(c.upiId||"UPI not recorded")+' · '+esc(c.mobile||"No mobile")+'<br>'+esc(c.note||"")+'</div></div><div>'+(c.status==="active"?'<button class="btn amber sm" onclick="SF.reverseMerchantCharge(\''+c.id+'\')">Reverse</button>':'<span class="badge">Reversed</span>')+'</div></div>'}).join("");s.innerHTML='<div class="toolbar"><div><h2>Merchant Charges</h2><div class="muted">Charges reduce available merchant settlement without changing collection history.</div></div><button class="btn primary" onclick="SF.addMerchantCharge()">Add Charge</button></div><div class="detailKpis">'+metric("Total Charges",money((db.merchantCharges||[]).filter(function(c){return c.status==="active"}).reduce(function(n,c){return n+c.amountInr},0)))+metric("Charge Records",(db.merchantCharges||[]).length)+metric("Available Settlement",money(Math.max(0,totals().collection-totals().frozen-totals().merchantSettled-(db.withdrawals||[]).filter(function(w){return w.requesterType==="merchant"&&["pending","paid"].includes(w.status)}).reduce(function(n,w){return n+w.amountInr},0))))+'</div>'+(rows||'<div class="empty">No charges</div>')}
function addMerchantCharge(){modal('<div class="modalBox"><div class="modalHead"><b>Add Merchant Charge</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+selectField("Related User","chargeProvider",db.users.filter(function(u){return u.status!=="deleted"}).map(function(u){return [u.id,u.name+" ("+u.id+")"]}),db.users[0]?.id||"")+field("Amount INR","chargeAmount","","number")+field("UPI Account ID (optional)","chargeUpi","")+field("UPI ID","chargeUpiId","")+field("Mobile","chargeMobile","")+field("Date","chargeDate",today(),"date")+field("Reference","chargeReference","")+field("Note","chargeNote","")+'</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveMerchantCharge()">Save Charge</button></div></div>')}
async function saveMerchantCharge(){var u=db.users.find(function(x){return x.id===v("chargeProvider")}),amount=Number(v("chargeAmount")||0);if(!u||amount<=0)return toast("User and positive amount required");try{await backend.addMerchantCharge({provider_id:u.remoteId,upi_account_id:v("chargeUpi")||null,amount_inr:amount,user_name:u.name,upi_id:v("chargeUpiId")||u.upi,mobile:v("chargeMobile")||u.mobile,charge_date:v("chargeDate")||today(),reference:v("chargeReference"),note:v("chargeNote"),idempotency_key:id("charge")});close();await refreshFromBackend();toast("Charge saved");showChargesPage()}catch(err){toast(err.message||"Charge failed")}}
async function reverseMerchantCharge(cid){try{await backend.reverseMerchantCharge(cid,id("charge_reverse"));await refreshFromBackend();showChargesPage();toast("Charge reversed")}catch(err){toast(err.message||"Charge reversal failed")}}
function searchCards(q){var el=document.getElementById("cards");if(!el)return;q=(q||"").toLowerCase();var arr=db.users.filter(function(u){return u.status!=="deleted"&&u.active!==false&&(u.name+" "+u.upi+" "+u.mobile+" "+u.telegram).toLowerCase().indexOf(q)>-1});el.innerHTML=arr.length?arr.map(function(u){return card(u,false)}).join(""):(backend.configured&&!backendHadLoaded?'<div class="empty">Loading users...</div>':'<div class="empty">No users</div>')}
function fillAdminTables(){var ut=document.getElementById("usersTable"),lt=document.getElementById("ledgerTable"),dt=document.getElementById("depositTable"),sb=document.getElementById("shareBody");if(ut)ut.innerHTML='<div class="tableWrap"><table><thead><tr><th>User</th><th>Mode</th><th>Collection</th><th>Available Capacity</th><th>Admin Limit</th><th>Deposit Value</th><th>Pending</th><th>Action</th></tr></thead><tbody>'+db.users.filter(function(u){return u.status!=="deleted"&&u.active!==false}).map(function(u){var c=calc(u);return '<tr><td><b>'+esc(u.name)+'</b><br><span class="muted">'+esc(u.id)+'</span></td><td>'+modePill(u)+'</td><td>'+money(c.collection)+'</td><td><b>'+money(c.collectionCapacity)+'</b></td><td>'+(u.fundingMode==="commission"?money(u.limit):'<span class="muted">Deposit driven</span>')+'</td><td>'+money(c.confirmedDepositINR)+'</td><td>'+money(c.pending)+'</td><td><button class="btn primary sm" onclick="SF.openUser(\''+u.id+'\')">Open</button></td></tr>'}).join("")+'</tbody></table></div>';
if(lt){var all=db.entries.slice().sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""))});lt.innerHTML='<div class="tableWrap"><table><thead><tr><th>Date</th><th>User</th><th>Type</th><th>Amount</th><th>Rate</th><th>Bank / Ref</th><th>Entered By</th></tr></thead><tbody>'+all.map(function(e){var u=db.users.find(function(x){return x.id===e.userId});return '<tr><td>'+dateFmt(e.date)+'</td><td>'+esc(u?u.name:e.userId)+'</td><td>'+esc(label(e.type))+'</td><td>'+(e.usdt?usdt(e.usdt):money(e.amount))+'</td><td>'+(e.rate?money(e.rate):'-')+'</td><td>'+esc((e.bank||"")+(e.account?" / "+e.account:"")+(e.note?" • "+e.note:""))+'</td><td>'+esc(e.enteredBy||"admin")+'</td></tr>'}).join("")+'</tbody></table></div>'}
if(dt){var arr=db.deposits.slice().sort(function(a,b){return String(b.createdAt||"").localeCompare(String(a.createdAt||""))});dt.innerHTML=arr.length?'<div class="tableWrap"><table><thead><tr><th>Created</th><th>User</th><th>USDT</th><th>Rate</th><th>INR Credit</th><th>Address</th><th>Status</th><th>TX Hash</th><th>Action</th></tr></thead><tbody>'+arr.map(function(d){var u=db.users.find(function(x){return x.id===d.userId});return '<tr><td>'+dateFmt(d.createdAt)+'</td><td>'+esc(u?u.name:d.userId)+'</td><td>'+usdt(d.requestedUsdt)+'</td><td>'+money(d.rate)+'</td><td>'+money(d.inrValue)+'</td><td style="max-width:180px;word-break:break-all">'+esc(d.address||"Not configured")+'</td><td><span class="badge '+(d.status==="confirmed"?'green':d.status==="failed"?'red':'amber')+'">'+esc(d.status)+'</span></td><td style="max-width:170px;word-break:break-all">'+esc(d.txHash||"-")+'</td><td>'+(d.status!=="confirmed"?'<button class="btn ghost sm" onclick="SF.checkDeposit(\''+d.id+'\',true)">Check</button> <button class="btn green sm" onclick="SF.simulateConfirm(\''+d.id+'\')">Demo Confirm</button>':'<span class="muted">Confirmed</span>')+'</td></tr>'}).join("")+'</tbody></table></div>':'<div class="empty">No deposits yet.</div>'}
if(sb)sb.innerHTML='<div class="box" style="padding:16px"><h3>Merchant Common Link</h3><div class="shareLine"><input readonly value="'+esc(merchantLink())+'"><button class="btn sm" onclick="SF.copy(\''+esc(merchantLink())+'\')">Copy</button><button class="btn primary sm" onclick="window.open(\''+esc(merchantLink())+'\',\'_blank\')">Open</button><button class="btn amber sm" onclick="SF.regen(\'merchant\')">Regenerate</button></div><h3 style="margin-top:20px">Agent Common Link</h3><div class="shareLine"><input readonly value="'+esc(agentLink())+'"><button class="btn sm" onclick="SF.copy(\''+esc(agentLink())+'\')">Copy</button><button class="btn primary sm" onclick="window.open(\''+esc(agentLink())+'\',\'_blank\')">Open</button><button class="btn amber sm" onclick="SF.regen(\'agent\')">Regenerate</button></div><h3 style="margin-top:20px">Individual User Links</h3>'+db.users.filter(function(u){return u.status!=="deleted"&&u.active!==false}).map(function(u){return '<div class="shareLine"><input readonly value="'+esc(userLink(u))+'"><span style="min-width:130px;font-size:12px">'+esc(u.name)+'</span><button class="btn sm" onclick="SF.copyUser(\''+u.id+'\')">Copy</button><button class="btn amber sm" onclick="SF.regenUser(\''+u.id+'\')">Regenerate</button></div>'}).join("")+'</div>'}
function addUser(){modal('<div class="modalBox small"><div class="modalHead"><div><b>Create User Card</b><div class="muted" style="font-size:12px">Name, Telegram and funding model are required.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+field("User Name","newName","")+field("Telegram Username","newTg","")+selectField("Funding Model","newMode",[["deposit","Deposit Based"],["commission","Commission Based (3.5%)"]],"deposit")+'<div class="field full"><div class="notice green"><b>Deposit Based:</b> confirmed TRC20 USDT creates collection capacity at the configured deposit rate.<br><b>Commission Based:</b> Admin assigns the internal limit and the user earns commission on successful INR withdrawals.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.createUser()">Create Card</button></div></div>')}
async function createUser(){var name=v("newName"),tg=v("newTg"),mode=v("newMode");if(!name||!tg)return toast("User Name and Telegram Username required");if(mode!=="deposit"&&mode!=="commission")return toast("Select Deposit Based or Commission Based");var n=1001+db.users.length;while(db.users.some(function(u){return u.id==="USR-"+n}))n++;var u={id:"USR-"+n,name:name,telegram:tg,upi:"",mobile:"",apk:"",gpayLogin:"",qrs:[],fundingMode:mode,limit:0,depositAddress:"",token:tok(),active:true};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(u);u.remoteId=result.data&&result.data.id;close();toast((mode==="deposit"?"Deposit Based":"Commission Based")+" user card created");await refreshFromBackend()}catch(err){toast(err.message||"User creation failed")}return}db.users.push(u);audit("user_created",u.id,"Created with Name + Telegram • "+(mode==="deposit"?"Deposit Based":"Commission Based"),"admin");close();save();toast((mode==="deposit"?"Deposit Based":"Commission Based")+" user card created")}
function editUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox"><div class="modalHead"><div><b>Edit User / Mode</b><div class="muted" style="font-size:12px">Admin can configure remaining card details after creation.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+field("User Name","uName",u.name)+field("Telegram Username","uTg",u.telegram)+field("UPI ID","uUpi",u.upi)+field("Mobile Number","uMob",u.mobile)+field("APK Mobile Number","uApk",u.apk)+field("GPay Login ID","uGpayLogin",u.gpayLogin)+selectField("Funding Model","uMode",[["commission","Commission Based — 3.5%"],["deposit","Deposit Based — USDT prepaid"]],u.fundingMode)+field("Admin Maximum Limit (Commission Mode)","uLimit",u.limit,"number")+field("Unique TRC20 Deposit Address (optional)","uDepositAddress",u.depositAddress||"")+'<div class="field full"><div class="notice">Deposit users use the unique address above when set; otherwise the global Admin TRC20 address is used. For production auto-matching, a unique address per user is recommended.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveUser(\''+uid+'\')">Save User</button></div></div>')}
async function saveUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;var before=JSON.stringify({name:u.name,telegram:u.telegram,mode:u.fundingMode,limit:u.limit,addr:u.depositAddress});var draft={...u,name:v("uName"),telegram:v("uTg"),upi:v("uUpi"),mobile:v("uMob"),apk:v("uApk"),gpayLogin:v("uGpayLogin"),fundingMode:v("uMode")||"commission",limit:Math.max(0,Number(v("uLimit")||0)),depositAddress:v("uDepositAddress")};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(draft);if(Number(result.data?.commission_limit_inr||0)!==draft.limit)throw new Error("Limit was not persisted");audit("user_updated",uid,"Before: "+before,"admin");close();await refreshFromBackend();toast("User updated")}catch(err){toast(err.message||"User update failed")}return}Object.assign(u,draft);audit("user_updated",uid,"Before: "+before,"admin");close();save();toast("User updated")}
function statusNotice(u){return u.status==="paused"?'<div class="notice amber" style="margin:15px 0"><b>ACCOUNT PAUSED</b><br>Reason: '+esc(u.pauseReason||"Temporarily unavailable")+'</div>':''}
function adminStatusButtons(u){if(staffRole!=="admin")return "";return u.status==="paused"?'<button class="btn amber sm" onclick="SF.resumeUser(\''+u.id+'\')">Resume</button><button class="btn red sm" onclick="SF.deleteUser(\''+u.id+'\')">Delete</button>':'<button class="btn amber sm" onclick="SF.pauseUser(\''+u.id+'\')">Pause</button><button class="btn red sm" onclick="SF.deleteUser(\''+u.id+'\')">Delete</button>'}
function pauseUser(uid){if(staffRole!=="admin")return toast("Admin permission required");var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox small"><div class="modalHead"><b>Pause User</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="muted">User: '+esc(u.name)+'<br>User ID: '+esc(u.id)+'</div><div class="field" style="margin-top:14px"><label>Reason for pause</label><textarea id="pauseReason" rows="4"></textarea></div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn amber" onclick="SF.confirmPause(\''+uid+'\')">Pause User</button></div></div>')}
async function confirmPause(uid){var reason=v("pauseReason");if(!reason)return toast("Pause reason is required");return changeProviderStatus(uid,"pause",reason)}
function deleteUser(uid){if(staffRole!=="admin")return toast("Admin permission required");var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox small"><div class="modalHead"><b>Delete User Permanently From Operations?</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="muted">User: '+esc(u.name)+'<br>User ID: '+esc(u.id)+'</div><div class="notice amber" style="margin-top:14px">This user will no longer be available for operations. Financial and audit history will be preserved.</div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn red" onclick="SF.confirmDelete(\''+uid+'\')">Delete User</button></div></div>')}
async function confirmDelete(uid){return changeProviderStatus(uid,"delete","")}
async function resumeUser(uid){if(staffRole!=="admin")return toast("Admin permission required");return changeProviderStatus(uid,"resume","")}
async function changeProviderStatus(uid,action,reason){var u=db.users.find(function(x){return x.id===uid});if(!u)return;try{if(backend.configured&&u.remoteId){await backend.updateProviderStatus(u.remoteId,action,reason);close();toast(action==="pause"?"User paused":action==="delete"?"User deleted":"User resumed");await refreshFromBackend()}else{u.status=action==="pause"?"paused":action==="delete"?"deleted":"active";u.active=u.status!=="deleted";u.pauseReason=action==="pause"?reason:"";audit(action==="pause"?"provider_paused":action==="delete"?"provider_deleted":"provider_resumed",uid,reason||"","admin");close();save();toast(action==="pause"?"User paused":action==="delete"?"User deleted":"User resumed")}}catch(err){toast(err.message||"Provider status update failed")}}
function setCommissionLimit(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;if(u.fundingMode!=="commission")return toast("Maximum limit applies only to Commission Based users");var c=calc(u);modal('<div class="modalBox small"><div class="modalHead"><div><b>Set Commission User Limit</b><div class="muted" style="font-size:12px">Admin-only capacity control for '+esc(u.name)+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody">'+field("Maximum Collection Limit INR","commissionLimit",u.limit,"number")+'<div class="notice" style="margin-top:12px">Current collection: <b>'+money(c.collection)+'</b><br>Successful withdrawal: <b>'+money(c.inrReceived)+'</b><br>Current available: <b>'+money(c.collectionCapacity)+'</b><br><br>This limit is never shown to Merchant, Agent or the User.</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveCommissionLimit(\''+uid+'\')">Save Limit</button></div></div>')}
async function saveCommissionLimit(uid){var u=db.users.find(function(x){return x.id===uid});if(!u||u.fundingMode!=="commission")return;var n=Number(v("commissionLimit")||0);if(n<0)return toast("Enter a valid limit");var old=Number(u.limit||0),draft={...u,limit:n};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(draft);if(Number(result.data?.commission_limit_inr||0)!==n)throw new Error("Limit was not persisted");audit("commission_limit_updated",uid,"From "+money(old)+" to "+money(n),"admin");close();await refreshFromBackend();toast("Commission user limit updated")}catch(err){toast(err.message||"Commission limit update failed")}return}u.limit=n;audit("commission_limit_updated",uid,"From "+money(old)+" to "+money(n),"admin");close();save();toast("Commission user limit updated")}
function settings(){modal('<div class="modalBox"><div class="modalHead"><div><b>System Settings</b><div class="muted" style="font-size:12px">Settlement, deposit credit, commission and TRON watcher configuration.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+field("Merchant Settlement Rate INR / USDT","sSettlement",db.settings.settlementRate,"number")+field("Deposit Base Rate INR / USDT","sBase",db.settings.depositBaseRate,"number")+field("Deposit Markup %","sMarkup",db.settings.depositMarkupPct,"number")+field("Commission % on Successful INR Withdrawal","sCommission",db.settings.commissionRate,"number")+field("Global Admin TRC20 Address","sAddress",db.settings.adminTrc20Address)+field("TRON USDT Contract","sContract",db.settings.usdtContract||USDT_CONTRACT)+ '<div class="field"><label>Calculated Deposit Rate</label><input disabled value="'+money(depositRate())+' / USDT"></div><div class="field full"><div class="notice amber"><b>Production security:</b> do not expose TronGrid API keys, GPay encryption keys or service-role keys in browser code. Run the blockchain watcher and credential decryption on a trusted backend/worker.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveSettings()">Save Settings</button></div></div>')}
async function saveSettings(){var next={settlementRate:Math.max(.01,Number(v("sSettlement")||107)),depositBaseRate:Math.max(.01,Number(v("sBase")||107)),depositMarkupPct:Math.max(0,Number(v("sMarkup")||3)),commissionRate:Math.max(0,Number(v("sCommission")||3.5)),adminTrc20Address:v("sAddress"),usdtContract:v("sContract")||USDT_CONTRACT};if(JSON.stringify(next)===JSON.stringify(db.settings))return toast("No settings changes");if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.writeSettings(next);db.settings=next;audit("settings_updated","","Rates / TRON settings updated","admin");close();toast("Settings saved");await refreshFromBackend()}catch(err){toast(err.message||"Settings update failed")}return}db.settings=next;audit("settings_updated","","Rates / TRON settings updated","admin");close();save();toast("Settings saved")}
function credentialHTML(u,copyAllowed){var controls=backend.configured&&currentSharedRole===""?'<div class="cardActions"><button class="btn ghost sm" onclick="SF.manageCredentials(\''+u.id+'\')">Manage Password</button><button class="btn ghost sm" onclick="SF.revealCredentials(\''+u.id+'\')">Reveal Password</button></div>':'';return '<div class="credGrid"><div class="credBox"><span>GPay Login ID</span><div class="credValue"><code>'+esc(u.gpayLogin||"-")+'</code></div></div><div class="credBox"><span>GPay password</span><div class="credValue"><code>Managed securely by the production backend</code></div><div class="auditLine">Passwords are never stored or revealed in this browser.</div>'+controls+'</div></div>'}
