async function saveCredentials(uid){var u=db.users.find(function(x){return x.id===uid}),password=v("credentialPassword");if(!u||!password)return toast("Password required");try{await backend.saveCredential(u.remoteId,password);close();toast("Password saved securely")}catch(err){toast(err.message||"Credential save failed")}}
