function qrHTML(u,editable){u.qrs=u.qrs||[];if(!u.qrs.length)return '<div class="empty">No GPay QR codes uploaded.</div>';return '<div class="qrGrid">'+u.qrs.map(function(q,i){return '<div class="qrItem"><img src="'+q.data+'" alt="QR"><div class="qrName">'+esc(q.name||("QR "+(i+1)))+'</div><div class="qrActions"><button class="btn ghost sm" onclick="SF.openQR(\''+u.id+'\','+i+')">Open</button>'+(editable?'<button class="btn red sm" onclick="SF.removeQR(\''+u.id+'\','+i+')">Remove</button>':'')+'</div></div>'}).join("")+'</div>'}
function uploadQR(uid){var input=document.createElement("input");input.type="file";input.accept="image/*";input.multiple=true;input.onchange=function(){var u=db.users.find(function(x){return x.id===uid});if(!u)return;if(backend.configured&&u.remoteId){Promise.all(Array.from(input.files||[]).map(function(f){return backend.uploadQR(u.remoteId,f,f.name)})).then(function(){toast("QR uploaded");refreshFromBackend()}).catch(function(err){toast(err.message||"QR upload failed")})}else{Array.from(input.files||[]).forEach(function(f){var r=new FileReader();r.onload=function(){u.qrs=u.qrs||[];u.qrs.push({name:f.name,data:r.result,createdAt:nowIso()});save(true);render();toast("QR uploaded")};r.readAsDataURL(f)})}};input.click()}
function removeQR(uid,i){var u=db.users.find(function(x){return x.id===uid}),qr=u&&u.qrs[i];if(!u||!qr)return;if(backend.configured&&qr.id){backend.deleteQR(qr).then(function(){toast("QR removed");refreshFromBackend()}).catch(function(err){toast(err.message||"QR delete failed")})}else{u.qrs.splice(i,1);save();toast("QR removed")}}
function openQR(uid,i){var u=db.users.find(function(x){return x.id===uid});if(u&&u.qrs[i])window.open(u.qrs[i].data,"_blank")}
function openUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;var c=calc(u),es=entries(uid).slice().sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""))}),ds=deposits(uid).slice().sort(function(a,b){return String(b.createdAt||"").localeCompare(String(a.createdAt||""))});var modeControl=u.fundingMode==="commission"?'<div class="box" style="padding:16px;margin-top:14px"><div class="toolbar"><div><h3>Commission User Capacity</h3><div class="muted">Admin-only limit. Withdrawals refill capacity up to this maximum.</div></div><button class="btn primary" onclick="SF.setCommissionLimit(\''+uid+'\')">Set / Change Limit</button></div><div class="detailKpis">'+metric("Maximum Limit",money(u.limit))+metric("Current Exposure",money(Math.max(0,c.collection-c.inrReceived)))+metric("Available Limit",money(c.collectionCapacity))+metric("Commission Earned",money(c.commissionEarned))+'</div></div>':'<div class="box" style="padding:16px;margin-top:14px"><div class="toolbar"><div><h3>Deposit User Capacity</h3><div class="muted">Capacity comes only from confirmed USDT deposits. INR withdrawals are tracked separately and do not refill deposit capacity.</div></div></div><div class="detailKpis">'+metric("Confirmed Deposit",usdt(c.confirmedDepositUsdt))+metric("Deposit INR Credit",money(c.confirmedDepositINR))+metric("Available Deposit Balance",money(c.collectionCapacity))+metric("Successful Withdrawal",money(c.inrReceived))+'</div></div>';modal('<div class="modalBox"><div class="modalHead"><div><b>'+esc(u.name)+'</b><div class="muted" style="font-size:12px">'+esc(u.id)+' • '+esc(u.telegram||"-")+' • '+(u.fundingMode==="deposit"?'Deposit Based':'Commission Based')+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="tabs"><button class="active" onclick="SF.tab(this,\'overview\')">Overview</button><button onclick="SF.tab(this,\'gpay\')">GPay Details</button><button onclick="SF.tab(this,\'history\')">History</button><button onclick="SF.tab(this,\'deposit\')">Deposits</button><button onclick="SF.tab(this,\'links\')">Share Links</button></div><div class="modalBody"><div id="p-overview" class="pane active"><div class="detailKpis">'+metric("Total Collection",money(c.collection))+metric("Successful Withdrawal",money(c.inrReceived))+metric("Pending From User",money(c.pending))+metric("Available Collection",money(c.collectionCapacity))+metric("Frozen",money(c.frozen))+metric("Merchant Available INR",money(c.merchantAvailableINR))+metric("Merchant Available USDT",usdt(c.merchantAvailableUSDT))+'</div>'+modeControl+statusNotice(u)+adminStatusButtons(u)+'<div class="notice '+(u.fundingMode==="deposit"?'green':'')+'" style="margin-top:12px">'+(u.fundingMode==="deposit"?'DEPOSIT LOGIC: Confirmed USDT × '+money(depositRate())+' creates capacity. Collection consumes capacity. Successful INR withdrawal is allowed and reduces Pending From User, but does NOT refill deposit capacity. Only a new confirmed USDT deposit refills it.':'COMMISSION LOGIC: Admin Maximum Limit − (Collection − Successful INR Withdrawal) = Available Collection, capped at the Admin Maximum Limit. '+num(db.settings.commissionRate)+'% commission is earned only on successful INR withdrawals.')+'</div><div class="cardActions" style="margin-top:14px"><button class="btn primary" onclick="SF.adminAddCollection(\''+uid+'\')">+ Collection</button><button class="btn green" onclick="SF.addEntry(\''+uid+'\',\'inr_received\')">+ INR Withdrawal</button><button class="btn" onclick="SF.addEntry(\''+uid+'\',\'user_usdt\')">+ USDT From User</button><button class="btn" onclick="SF.addEntry(\''+uid+'\',\'merchant_usdt\')">+ Merchant USDT</button><button class="btn red" onclick="SF.addEntry(\''+uid+'\',\'frozen\')">+ Frozen</button><button class="btn ghost" onclick="SF.editUser(\''+uid+'\')">Edit User / Mode</button></div></div><div id="p-gpay" class="pane"><div class="toolbar"><div><h3>Google Pay Details</h3><div class="muted">UPI, APK/mobile, credentials and QR codes.</div></div><button class="btn ghost" onclick="SF.editUser(\''+uid+'\')">Edit Details</button></div><div class="credGrid"><div class="credBox"><span>UPI ID</span><div class="credValue"><code>'+esc(u.upi||"-")+'</code></div></div><div class="credBox"><span>APK / Mobile Number</span><div class="credValue"><code>'+esc(u.apk||u.mobile||"-")+'</code></div></div></div>'+credentialHTML(u,true)+'<div class="toolbar" style="margin-top:18px"><div><h3>GPay QR Codes</h3><div class="muted">All QR codes attached to this card.</div></div><button class="btn primary" onclick="SF.uploadQR(\''+uid+'\')">+ Upload QR Codes</button></div>'+qrHTML(u,true)+'</div><div id="p-history" class="pane">'+(es.length?es.map(function(e){return entryRow(e,true)}).join(""):'<div class="empty">No ledger history</div>')+'</div><div id="p-deposit" class="pane">'+(u.fundingMode==="deposit"?'<div class="notice green">User can create deposits from the individual User link. Admin can monitor or demo-confirm them here.</div>':'<div class="notice">This user is Commission Based. Deposit creation is disabled unless Admin changes the funding model.</div>')+'<div style="margin-top:12px">'+(ds.length?ds.map(function(d){return depositRow(d,true)}).join(""):'<div class="empty">No deposits</div>')+'</div></div><div id="p-links" class="pane"><h3>Individual User Link</h3><div class="shareLine"><input readonly value="'+esc(userLink(u))+'"><button class="btn sm" onclick="SF.copyUser(\''+u.id+'\')">Copy</button><button class="btn primary sm" onclick="window.open(\''+esc(userLink(u))+'\',\'_blank\')">Open</button><button class="btn amber sm" onclick="SF.regenUser(\''+u.id+'\')">Regenerate</button></div><h3 style="margin-top:20px">Merchant Link</h3><div class="shareLine"><input readonly value="'+esc(merchantLink())+'"><button class="btn sm" onclick="SF.copy(\''+esc(merchantLink())+'\')">Copy</button></div><h3 style="margin-top:20px">Agent Link</h3><div class="shareLine"><input readonly value="'+esc(agentLink())+'"><button class="btn sm" onclick="SF.copy(\''+esc(agentLink())+'\')">Copy</button></div></div></div></div>')}
function tab(b,name){var box=b.closest(".modalBox");box.querySelectorAll(".tabs button").forEach(function(x){x.classList.remove("active")});b.classList.add("active");box.querySelectorAll(".pane").forEach(function(x){x.classList.remove("active")});var p=box.querySelector("#p-"+name);if(p)p.classList.add("active")}
function entryRow(e,adminMode){var amount=e.usdt?usdt(e.usdt):money(e.amount);var status=e.type==="frozen"?(e.status||"active"):(e.status||"posted");return '<div class="entry"><div><b style="font-size:11px">'+esc(label(e.type))+'</b><div class="muted" style="font-size:10px">'+dateFmt(e.date)+'</div></div><div><b>'+amount+'</b><div class="muted" style="font-size:11px">'+esc((e.bank||"")+(e.account?" / "+e.account:"")+(e.note?" • "+e.note:""))+'</div>'+(e.previousAmount!=null?'<div class="auditLine">Corrected from '+money(e.previousAmount)+' • '+esc(e.updatedBy||"admin")+'</div>':'')+'</div><div>'+(adminMode?'<button class="btn ghost sm" onclick="SF.editEntry(\''+e.id+'\')">Edit</button> ':'')+(e.type==="frozen"&&e.status!=="released"&&adminMode?'<button class="btn green sm" onclick="SF.release(\''+e.id+'\')">Release</button>':'<span class="badge '+(status==="released"?'green':'')+'">'+esc(status)+'</span>')+'</div></div>'}
function adminAddCollection(uid){openCollectionForm(uid,"admin")}
function openCollectionForm(uid,actor){var u=db.users.find(function(x){return x.id===uid}),c=calc(u);modal('<div class="modalBox" style="max-width:680px"><div class="modalHead"><div><b>Add Collection</b><div class="muted" style="font-size:12px">'+esc(u.name)+' • Available capacity '+money(c.collectionCapacity)+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="notice">System blocks collection above current available capacity.</div><div class="form" style="margin-top:12px">'+field("Bank Name","cBank","")+field("Account Number","cAccount","")+field("Collection Amount","cAmount","","number")+field("Date","cDate",today(),"date")+'<div class="field full"><label>Note / Reference</label><input id="cNote"></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveCollection(\''+uid+'\',\''+actor+'\')">Save Collection</button></div></div>')}
async function saveCollection(uid,actor){var u=db.users.find(function(x){return x.id===uid}),c=calc(u),amount=Number(v("cAmount")||0),bank=v("cBank"),account=v("cAccount"),date=v("cDate"),note=v("cNote");if(amount<=0)return toast("Enter valid collection amount");if(!bank||!account||!date)return toast("Bank, account and date required");if(u.fundingMode==="commission"&&Number(u.limit||0)<=0)return toast("Collection limit not configured");if(amount>c.collectionCapacity+0.0001)return toast("Collection exceeds available limit: "+money(c.collectionCapacity));var e={id:id("e"),userId:uid,type:"collection",bank:bank,account:account,amount:amount,date:date,note:note,status:"posted",createdAt:nowIso(),updatedAt:nowIso(),enteredBy:actor,idempotencyKey:id("idem")};if(backend.configured&&currentSharedRole==="Merchant"){try{await backend.shareAction(location.hash.split("=")[1],{action:"collection",provider_id:u.remoteId,amount_inr:amount,bank_name:bank,account_number:account,transaction_date:date,note:note,idempotency_key:e.idempotencyKey});toast("Collection added");var remote=await backend.resolveShare(location.hash.split("=")[1]);db=remote.state;render()}catch(err){toast(err.message||"Collection failed")}return}if(backend.configured){if(await targetedLedger(e,u)){close();toast("Collection added")}return}db.entries.push(e);audit("collection_added",uid,money(amount)+" by "+actor,actor);close();save();toast("Collection added")}
function addEntry(uid,type){var title={inr_received:"Record Successful INR Withdrawal",user_usdt:"Record USDT From User",merchant_usdt:"Merchant USDT Settlement",frozen:"Add Frozen Fund"}[type];var x="";if(type==="frozen")x=field("Bank Name","eBank","")+field("Frozen Amount INR","eAmount","","number");else if(type==="inr_received")x=field("Successful INR Withdrawal Received","eAmount","","number");else x=field("USDT Amount","eUsdt","","number")+field("Historical Rate","eRate",db.settings.settlementRate,"number");modal('<div class="modalBox" style="max-width:680px"><div class="modalHead"><b>'+title+'</b><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+x+field("Date","eDate",today(),"date")+'<div class="field full"><label>Note / Reference</label><input id="eNote"></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveEntry(\''+uid+'\',\''+type+'\')">Save Entry</button></div></div>')}
async function saveEntry(uid,type){var u=db.users.find(function(x){return x.id===uid}),e={id:id("e"),userId:uid,type:type,date:v("eDate"),note:v("eNote"),status:"posted",createdAt:nowIso(),updatedAt:nowIso(),enteredBy:"admin"};if(type==="inr_received"||type==="frozen"){e.amount=Number(v("eAmount")||0);if(e.amount<=0)return toast("Enter valid amount")}if(type==="frozen"){e.bank=v("eBank");e.status="active";if(!e.bank)return toast("Bank required")}if(type==="user_usdt"||type==="merchant_usdt"){e.usdt=Number(v("eUsdt")||0);e.rate=Number(v("eRate")||db.settings.settlementRate);if(e.usdt<=0||e.rate<=0)return toast("Enter valid USDT and rate")}if(backend.configured){if(await targetedLedger(e,u)){close();toast("Entry saved")}return}db.entries.push(e);audit(type+"_added",uid,(e.usdt?usdt(e.usdt):money(e.amount)),"admin");close();save();toast("Entry saved")}
function editEntry(eid){var e=db.entries.find(function(x){return x.id===eid});if(!e)return;var fields="";if(e.type==="collection")fields=field("Bank Name","eeBank",e.bank||"")+field("Account Number","eeAccount",e.account||"")+field("Amount INR","eeAmount",e.amount||0,"number");else if(e.type==="frozen")fields=field("Bank Name","eeBank",e.bank||"")+field("Frozen Amount INR","eeAmount",e.amount||0,"number");else if(e.type==="inr_received")fields=field("INR Amount","eeAmount",e.amount||0,"number");else fields=field("USDT Amount","eeUsdt",e.usdt||0,"number")+field("Historical Rate","eeRate",e.rate||db.settings.settlementRate,"number");modal('<div class="modalBox" style="max-width:680px"><div class="modalHead"><b>Edit '+esc(label(e.type))+'</b><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+fields+field("Date","eeDate",e.date,"date")+'<div class="field full"><label>Correction Reason / Note</label><input id="eeNote" value="'+esc(e.note||"")+'"></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.updateEntry(\''+eid+'\')">Save Correction</button></div></div>')}
async function updateEntry(eid){var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId});if(!e||!u)return;var old=e.usdt!=null?Number(e.usdt):Number(e.amount||0);e.date=v("eeDate");e.note=v("eeNote");if(e.type==="collection"||e.type==="inr_received"||e.type==="frozen")e.amount=Math.max(0,Number(v("eeAmount")||0));if(e.type==="collection"){e.bank=v("eeBank");e.account=v("eeAccount")}if(e.type==="frozen")e.bank=v("eeBank");if(e.type==="user_usdt"||e.type==="merchant_usdt"){e.usdt=Math.max(0,Number(v("eeUsdt")||0));e.rate=Math.max(.01,Number(v("eeRate")||db.settings.settlementRate))}e.previousAmount=old;e.updatedAt=nowIso();e.updatedBy="admin";if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.updateLedger(e,u.remoteId);close();toast("Correction saved");await refreshFromBackend()}catch(err){toast(err.message||"Ledger correction failed")}return}audit("ledger_corrected",e.userId,label(e.type)+" corrected from "+old,"admin");close();save();toast("Correction saved")}
async function release(eid){var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId});if(!e||!u)return;if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.releaseLedger(e.id,u.remoteId);close();toast("Frozen amount released");await refreshFromBackend()}catch(err){toast(err.message||"Frozen release failed")}return}e.status="released";e.releaseDate=today();e.updatedAt=nowIso();audit("frozen_released",e.userId,money(e.amount),"admin");close();save();toast("Frozen amount released")}
function depositRow(d,adminMode){return '<div class="entry"><div><b>TRC20 Deposit</b><div class="muted" style="font-size:10px">'+dateFmt(d.createdAt)+'</div></div><div><b>'+usdt(d.requestedUsdt)+' → '+money(d.inrValue)+'</b><div class="muted" style="font-size:11px">Rate '+money(d.rate)+' • '+esc(d.address||"No address")+'</div><div class="auditLine"><span class="statusDot '+(d.status==="confirmed"?'confirmed':d.status==="failed"?'failed':'')+'"></span>'+esc(d.status)+' '+(d.txHash?'• '+esc(d.txHash):'')+'</div></div><div>'+(adminMode&&d.status!=="confirmed"?'<button class="btn ghost sm" onclick="SF.checkDeposit(\''+d.id+'\',true)">Check</button> <button class="btn green sm" onclick="SF.simulateConfirm(\''+d.id+'\')">Demo Confirm</button>':'<span class="badge '+(d.status==="confirmed"?'green':'amber')+'">'+esc(d.status)+'</span>')+'</div></div>'}
function createDepositPage(uid){var u=db.users.find(function(x){return x.id===uid});if(!u||u.fundingMode!=="deposit")return toast("Deposit mode required");var addr=u.depositAddress||db.settings.adminTrc20Address||"";modal('<div class="modalBox"><div class="modalHead"><div><b>Create USDT Deposit</b><div class="muted" style="font-size:12px">TRC20 • 1 USDT = '+money(depositRate())+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="depositHero"><div class="depositPanel"><h2 style="margin-top:0">Enter Deposit Amount</h2>'+field("USDT Amount","depAmount","","number")+'<div class="notice green" style="margin-top:12px">Every confirmed 1 USDT adds <b>'+money(depositRate())+'</b> to your collection balance.</div><div class="cardActions"><button class="btn primary" onclick="SF.generateDeposit(\''+uid+'\')">Generate Deposit QR</button></div><div class="securityNote">Blockchain confirmation is automatic when the watcher can query TronGrid. This standalone prototype also includes a Demo Confirm button for testing.</div></div><div class="depositPanel depositQR"><div style="text-align:center"><div class="muted">Deposit address</div><div style="font-size:13px;margin-top:8px;word-break:break-all">'+esc(addr||"Admin has not configured a TRC20 address yet.")+'</div></div></div></div></div></div>')}
async function generateDeposit(uid){var u=db.users.find(function(x){return x.id===uid}),amount=Number(v("depAmount")||0);if(amount<=0)return toast("Enter valid USDT amount");if(backend.configured&&currentSharedRole==="User"){try{var result=await backend.shareAction(location.hash.split("=")[1],{action:"deposit",amount_usdt:amount});toast("Deposit request created");var remote=await backend.resolveShare(location.hash.split("=")[1]);db=remote.state;showDepositRequest(result.data.id)}catch(err){toast(err.message||"Deposit request failed")}return}var addr=u.depositAddress||db.settings.adminTrc20Address||"";if(!addr)return toast("Admin must configure a TRC20 address first");var rate=depositRate(),d={id:id("dep"),userId:uid,requestedUsdt:amount,expectedUsdt:amount,rate:rate,inrValue:amount*rate,address:addr,status:"waiting",txHash:"",createdAt:nowIso(),confirmedAt:"",source:"user"};db.deposits.push(d);audit("deposit_created",uid,usdt(amount)+" at "+money(rate),"user");save(true);showDepositRequest(d.id)}
function paymentPayload(d){return "USDT TRC20\nAddress: "+d.address+"\nAmount: "+Number(d.expectedUsdt).toFixed(6)}
function qrUrl(d){return "https://quickchart.io/qr?size=320&text="+encodeURIComponent(paymentPayload(d))}
function showDepositRequest(did){var d=db.deposits.find(function(x){return x.id===did}),u=db.users.find(function(x){return x.id===d.userId});if(!d)return;modal('<div class="modalBox"><div class="modalHead"><div><b>Deposit Request</b><div class="muted" style="font-size:12px">'+esc(u?u.name:d.userId)+' • '+esc(d.id)+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="depositHero"><div class="depositPanel"><div class="muted">Send exactly</div><div class="depositAmount">'+usdt(d.expectedUsdt)+'</div><div class="muted">Credit after confirmation</div><div style="font-size:22px;font-weight:900;margin:5px 0 16px">'+money(d.inrValue)+'</div><div class="addressBox">'+esc(d.address)+'</div><div class="cardActions"><button class="btn ghost" onclick="SF.copy(\''+esc(d.address)+'\',\'Address copied\')">Copy Address</button><button class="btn ghost" onclick="SF.copy(\''+d.expectedUsdt+'\',\'Amount copied\')">Copy Amount</button></div><div class="notice" style="margin-top:14px"><span class="statusDot '+(d.status==="confirmed"?'confirmed':'')+'"></span>Status: <b>'+esc(d.status.toUpperCase())+'</b>'+(d.txHash?'<br>TX: '+esc(d.txHash):'')+'</div><div class="cardActions"><button class="btn blue" onclick="SF.checkDeposit(\''+d.id+'\',true)">Check Blockchain</button>'+(d.status!=="confirmed"?'<button class="btn green" onclick="SF.simulateConfirm(\''+d.id+'\')">Demo Confirm</button>':'')+'</div></div><div class="depositPanel depositQR"><div><img src="'+qrUrl(d)+'" alt="Deposit QR"><div class="muted" style="text-align:center;margin-top:10px">TRC20 deposit QR</div></div></div></div></div></div>')}
function checkDeposit(did,manual){if(manual)toast("Blockchain confirmation requires the backend watcher; use Demo Confirm for local testing")}
function checkAllDeposits(manual){db.deposits.filter(function(d){return d.status!=="confirmed"}).forEach(function(d){checkDeposit(d.id,false)});if(manual)toast("Blockchain checks started")}
function simulateConfirm(did){var d=db.deposits.find(function(x){return x.id===did});if(!d||d.status==="confirmed")return;d.status="confirmed";d.txHash="DEMO_"+id("tx");d.confirmedAt=nowIso();d.source="demo";audit("deposit_confirmed_demo",d.userId,usdt(d.expectedUsdt),"demo");close();save();toast("Demo deposit confirmed")}
function simulateConfirm(did){if(backend.configured)return toast("Demo confirmation is disabled in production");var d=db.deposits.find(function(x){return x.id===did});if(!d||d.status==="confirmed")return;d.status="confirmed";d.txHash="DEMO_"+id("tx");d.confirmedAt=nowIso();d.source="demo";audit("deposit_confirmed_demo",d.userId,usdt(d.expectedUsdt),"demo");close();save();toast("Demo deposit confirmed")}
function startWatcher(){}
async function regen(kind){if(backend.configured){try{var result=await backend.callFunction("share-link",{action:"regenerate",scope:kind});var token=result.data&&result.data[0]&&result.data[0].token;if(!token)throw new Error("share token was not returned");backend.rememberShareToken(kind,"",token);if(kind==="merchant")db.settings.merchantToken=token;else db.settings.agentToken=token;toast(kind+" link regenerated");render()}catch(err){toast(err.message||"Share link failed")}}else{if(kind==="merchant")db.settings.merchantToken=tok();else db.settings.agentToken=tok();audit("share_regenerated","",kind,"admin");save();toast(kind+" link regenerated")}}
async function regenUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;if(backend.configured&&u.remoteId){try{var result=await backend.callFunction("share-link",{action:"regenerate",scope:"user",provider_id:u.remoteId});u.token=result.data&&result.data[0]&&result.data[0].token;if(!u.token)throw new Error("share token was not returned");backend.rememberShareToken("user",u.remoteId,u.token);toast("User link regenerated");render()}catch(err){toast(err.message||"Share link failed")}}else{u.token=tok();audit("user_share_regenerated",uid,"Individual link regenerated","admin");save();toast("User link regenerated")}}
function copyUser(uid){var u=db.users.find(function(x){return x.id===uid});if(u)copy(userLink(u),"User link copied")}
var currentSharedRole="";
