function pageFrame(title,body){var main=document.querySelector(".main");if(!main)return;main.querySelectorAll(".section").forEach(function(x){x.style.display="none"});var old=main.querySelector(".pageSurface");if(old)old.remove();var s=document.createElement("section");s.className="pageSurface section active";s.innerHTML='<div class="toolbar"><div><h2>'+esc(title)+'</h2></div></div>'+body;main.appendChild(s);return s}
function accountRow(u,a,actions){var c=accountCalc(u,a),state=a.merchantOperational===false||a.status!=="active"?"STOPPED":"RUNNING";return '<div class="listRow"><div><b>'+esc(u.name)+' · '+esc(a.label||"UPI")+'</b><div class="muted">'+esc(u.id)+' · '+esc(a.upi||"No UPI")+' · '+esc(a.mobile||a.apk||"No mobile")+' · '+modePill(u)+'</div></div><div><b>'+money(c.available)+'</b><div class="muted">Collection '+money(c.collection)+' · '+state+'</div></div><div class="cardActions">'+(actions||"")+'</div></div>'}
function allAccounts(){return db.users.flatMap(function(u){return (u.upiAccounts||[]).map(function(a){return {u:u,a:a}})})}
function adminPage(name){var active=db.users.filter(function(u){return u.status!=="deleted"}),rows="";
if(name==="users")rows='<div class="toolbar"><input class="search" placeholder="Search users" oninput="SF.filterPage(this.value,\'userRows\')"><button class="btn primary" onclick="SF.addUser()">Add User</button></div><div id="userRows">'+active.map(function(u){var t=calc(u);return '<div class="listRow"><div><b>'+esc(u.name)+'</b><div class="muted">'+esc(u.id)+' · '+modePill(u)+'</div></div><div><b>'+((u.upiAccounts||[]).length)+' UPI accounts</b><div class="muted">Collection '+money(t.collection)+' · Capacity '+money(t.collectionCapacity)+'</div></div><div class="cardActions"><button class="btn primary sm" onclick="SF.userPage(\''+u.id+'\')">Open User</button><button class="btn ghost sm" onclick="SF.addUpi(\''+u.id+'\')">Add UPI</button><button class="btn ghost sm" onclick="SF.editUser(\''+u.id+'\')">Edit User</button></div></div>'}).join("")+'</div>';
else if(name==="accounts")rows='<div class="toolbar"><input class="search" placeholder="Search user, UPI or mobile" oninput="SF.filterPage(this.value,\'accountRows\')"></div><div id="accountRows">'+allAccounts().map(function(x){return accountRow(x.u,x.a,'<button class="btn primary sm" onclick="SF.editUpi(\''+x.a.id+'\')">Edit</button><button class="btn ghost sm" onclick="SF.setUpiLimit(\''+x.a.id+'\')">Set Limit</button><button class="btn ghost sm" onclick="SF.upiCredentials(\''+x.a.id+'\')">GPay Details</button><button class="btn amber sm" onclick="SF.toggleUpi(\''+x.a.id+'\')">ON/OFF</button>')}).join("")+'</div>';
else if(name==="charges")return showChargesPage();
else if(name==="ledger"||name==="history"||name==="collections")rows=(db.entries||[]).map(function(e){var u=db.users.find(function(x){return x.id===e.userId}),a=(u?.upiAccounts||[]).find(function(x){return x.id===e.accountId});return '<div class="listRow"><div><b>'+label(e.type)+' · '+money(e.amount||0)+'</b><div class="muted">'+esc(u?.name||"Unknown")+' · '+esc(a?.label||a?.upi||"Legacy / Unassigned")+'</div></div><div class="muted">'+dateFmt(e.date)+'<br>'+esc(e.note||"")+'</div></div>'}).join("")||'<div class="empty">No records</div>';
else if(name==="deposits")rows=(db.deposits||[]).map(function(d){var u=db.users.find(function(x){return x.id===d.userId});return '<div class="listRow"><div><b>'+esc(u?.name||d.userId)+'</b><div class="muted">'+usdt(d.requestedUsdt)+' · '+money(d.inrValue)+'</div></div><span class="badge">'+esc(d.status)+'</span></div>'}).join("")||'<div class="empty">No deposits</div>';
else if(name==="commission"||name==="userWithdrawals"||name==="merchantWithdrawals")rows=(db.withdrawals||[]).map(function(w){var u=db.users.find(function(x){return x.id===w.userId});return '<div class="listRow"><div><b>'+esc(u?.name||w.requesterType)+'</b><div class="muted">'+usdt(w.amountUsdt)+' @ '+money(w.rate)+' = '+money(w.amountInr)+'</div></div><div>'+esc(w.status)+'</div>'+(w.status==="pending"?'<button class="btn primary sm" onclick="SF.markWithdrawal(\''+w.id+'\')">Mark Paid</button>':'')+'</div>'}).join("")||'<div class="empty">No withdrawals</div>';
else if(name==="settlement")rows='<div class="detailKpis">'+metric("Total Collection",money(totals().collection))+metric("Available Settlement",money(Math.max(0,totals().collection-totals().frozen-totals().merchantSettled)))+'</div><button class="btn primary" onclick="SF.manualMerchantSettlement()">Manual Settlement</button>';
else if(name==="frozen")rows=(db.entries||[]).filter(function(e){return e.type==="frozen"}).map(function(e){return '<div class="listRow"><b>'+money(e.amount)+'</b><span>'+esc(e.status||"active")+'</span></div>'}).join("")||'<div class="empty">No frozen funds</div>';
else if(name==="gpay")rows=allAccounts().map(function(x){return accountRow(x.u,x.a,'<button class="btn primary sm" onclick="SF.upiCredentials(\''+x.a.id+'\')">Manage GPay</button>')}).join("")||'<div class="empty">No UPI accounts</div>';
else if(name==="share")rows='<div class="tableWrap">'+(active.map(function(u){return '<div class="listRow"><div><b>'+esc(u.name)+'</b><div class="muted">'+esc(u.id)+'</div></div><code>'+esc(userLink(u))+'</code><button class="btn ghost sm" onclick="SF.copyUser(\''+u.id+'\')">Copy</button><button class="btn primary sm" onclick="SF.regenUser(\''+u.id+'\')">Regenerate</button></div>'}).join("")+'<div class="listRow"><b>Merchant</b><code>'+esc(merchantLink())+'</code></div><div class="listRow"><b>Agent</b><code>'+esc(agentLink())+'</code></div></div>');
else rows='<div class="detailKpis">'+metric("Users",active.length)+metric("UPI Accounts",allAccounts().length)+metric("Collections",money(totals().collection))+metric("Pending",money(totals().pending))+'</div><h3>Recent activity</h3>'+((db.entries||[]).slice(0,8).map(function(e){return entryRow(e,true)}).join("")||'<div class="empty">No recent activity</div>');
return pageFrame({dashboard:"Dashboard",users:"Users",accounts:"UPI Accounts",ledger:"Collections",history:"History / Audit",deposits:"Deposits",commission:"User Commission",userWithdrawals:"User Withdrawals",merchantSettlement:"Merchant Settlement",merchantWithdrawals:"Merchant Withdrawals",frozen:"Frozen",gpay:"GPay / QR",share:"Share Links"}[name]||name,rows)}
function filterPage(q,idv){var el=document.getElementById(idv);if(!el)return;var needle=(q||"").toLowerCase();el.querySelectorAll(".listRow").forEach(function(row){row.style.display=row.textContent.toLowerCase().indexOf(needle)>-1?"":"none"})}
function userPage(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;var pool=u.fundingMode==="deposit"?((u.accounting||{}).confirmed_deposit_inr||calc(u).confirmedDepositINR):u.limit,allocated=(u.upiAccounts||[]).reduce(function(n,a){return n+Number(a.allocatedLimit||0)},0),used=(u.upiAccounts||[]).reduce(function(n,a){return n+accountCalc(u,a).collection},0);pageFrame("User · "+u.name,'<div class="detailKpis">'+metric("Funding Mode",u.fundingMode)+metric("UPI Accounts",(u.upiAccounts||[]).length)+metric("Total Collection",money(calc(u).collection))+metric("Deposit Pool",money(pool))+metric("Allocated",money(allocated))+metric("Unallocated",money(Math.max(0,pool-allocated)))+'</div><div class="cardActions"><button class="btn primary" onclick="SF.addUpi(\''+uid+'\')">Add UPI Account</button><button class="btn ghost" onclick="SF.editUser(\''+uid+'\')">Edit User</button></div><div>'+((u.upiAccounts||[]).map(function(a){return accountRow(u,a,'<button class="btn ghost sm" onclick="SF.editUpi(\''+a.id+'\')">Edit</button><button class="btn primary sm" onclick="SF.setUpiLimit(\''+a.id+'\')">'+(u.fundingMode==="deposit"?"Change Allocation":"Set Limit")+'</button><button class="btn ghost sm" onclick="SF.upiCredentials(\''+a.id+'\')">GPay</button>')}).join("")||'<div class="empty">No child UPI accounts</div>')+'</div><h3>Used Capacity</h3><div class="notice">'+money(used)+' consumed. Consumed allocation cannot be moved.</div>')}
function addUpi(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox"><div class="modalHead"><b>Add UPI Account</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+field("Label","upiLabel","")+field("UPI ID","upiId","")+field("Mobile","upiMobile","")+field("APK","upiApk","")+field("GPay Login","upiLogin","")+field("Configured Limit / Allocation","upiLimit","0","number")+'</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveUpi(\''+uid+'\')">Create Account</button></div></div>')}
async function saveUpi(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;try{await backend.upsertUpiAccount({provider_id:u.remoteId,label:v("upiLabel"),upi_id:v("upiId"),mobile:v("upiMobile"),apk_mobile:v("upiApk"),gpay_login_id:v("upiLogin"),funding_model:u.fundingMode,configured_limit_inr:u.fundingMode==="commission"?Number(v("upiLimit")||0):0,allocated_limit_inr:u.fundingMode==="deposit"?Number(v("upiLimit")||0):0});close();await refreshFromBackend();userPage(uid);toast("UPI account created")}catch(err){toast(err.message||"UPI account failed")}}
function accountById(idv){var found=allAccounts().find(function(x){return x.a.id===idv});return found}
function editUpi(idv){var x=accountById(idv);if(!x)return;modal('<div class="modalBox"><div class="modalHead"><b>Edit UPI Account</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+field("Label","upiLabel",x.a.label)+field("UPI ID","upiId",x.a.upi)+field("Mobile","upiMobile",x.a.mobile)+field("APK","upiApk",x.a.apk)+field("GPay Login","upiLogin",x.a.gpayLogin)+'</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.updateUpi(\''+idv+'\',\''+x.u.remoteId+'\')">Save</button></div></div>')}
async function updateUpi(idv,pid){try{await backend.upsertUpiAccount({id:idv,provider_id:pid,label:v("upiLabel"),upi_id:v("upiId"),mobile:v("upiMobile"),apk_mobile:v("upiApk"),gpay_login_id:v("upiLogin")});close();await refreshFromBackend();adminPage("accounts");toast("UPI account updated")}catch(err){toast(err.message||"UPI update failed")}}
function setUpiLimit(idv){var x=accountById(idv);if(!x)return;var old=x.u.fundingMode==="deposit"?x.a.allocatedLimit:x.a.configuredLimit;modal('<div class="modalBox small"><div class="modalHead"><b>'+(x.u.fundingMode==="deposit"?"Change Allocation":"Set Limit")+'</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody">'+field("Amount INR","upiLimit",old,"number")+'</div><div class="modalFoot"><button class="btn primary" onclick="SF.saveUpiLimit(\''+idv+'\')">Save</button></div></div>')}
async function saveUpiLimit(idv){var x=accountById(idv),n=Number(v("upiLimit")||0);if(!x||n<0)return toast("Invalid amount");try{if(x.u.fundingMode==="deposit")await backend.allocateUpiCapacity(idv,n);else await backend.upsertUpiAccount({id:idv,provider_id:x.u.remoteId,label:x.a.label,upi_id:x.a.upi,mobile:x.a.mobile,apk_mobile:x.a.apk,gpay_login_id:x.a.gpayLogin,configured_limit_inr:n,allocated_limit_inr:0,funding_model:"commission"});close();await refreshFromBackend();adminPage("accounts");toast("Account limit saved")}catch(err){toast(err.message||"Limit update failed")}}
async function toggleUpi(idv){var x=accountById(idv);if(!x)return;try{await backend.callFunction("provider-write",{action:"upi_operational_status",upi_account_id:idv,merchant_operational:!(x.a.merchantOperational!==false&&x.a.status==="active")});await refreshFromBackend();adminPage("accounts")}catch(err){toast(err.message||"Status update failed")}}
function upiCredentials(idv){var x=accountById(idv);if(!x)return;modal('<div class="modalBox small"><div class="modalHead"><b>GPay · '+esc(x.a.label)+'</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody">'+field("Login", "upiLogin",x.a.gpayLogin)+field("New Password","upiPassword","","password")+'<div class="notice">Password is encrypted and omitted from account lists.</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveUpiCredential(\''+x.u.remoteId+'\',\''+idv+'\')">Save Password</button><button class="btn ghost" onclick="SF.revealUpiCredential(\''+x.u.remoteId+'\',\''+idv+'\')">Reveal</button></div></div>')}
function addMerchantCharge(){var opts=allAccounts().map(function(x){return [x.a.id,x.u.name+" · "+(x.a.label||"UPI")+" · "+(x.a.upi||"No UPI")]});modal('<div class="modalBox"><div class="modalHead"><b>Add Merchant Charge</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+selectField("UPI Account","chargeUpi",opts,opts[0]?.[0]||"")+field("Amount INR","chargeAmount","","number")+field("Date","chargeDate",today(),"date")+field("Reference","chargeReference","")+field("Note","chargeNote","")+'</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveMerchantCharge()">Save Charge</button></div></div>')}
async function saveMerchantCharge(){var x=accountById(v("chargeUpi")),amount=Number(v("chargeAmount")||0);if(!x||amount<=0)return toast("UPI account and positive amount required");try{await backend.addMerchantCharge({provider_id:x.u.remoteId,upi_account_id:x.a.id,amount_inr:amount,user_name:x.u.name,upi_id:x.a.upi,mobile:x.a.mobile||x.a.apk,charge_date:v("chargeDate")||today(),reference:v("chargeReference"),note:v("chargeNote"),idempotency_key:id("charge")});close();await refreshFromBackend();adminPage("charges");toast("Charge saved")}catch(err){toast(err.message||"Charge failed")}}
async function saveUpiCredential(pid,aid){try{if(v("upiPassword"))await backend.saveCredential(pid,v("upiPassword"),aid);close();toast("Credential saved")}catch(err){toast(err.message||"Credential save failed")}}
async function revealUpiCredential(pid,aid){try{var p=await backend.revealCredential(pid,aid);modal('<div class="modalBox small"><div class="modalHead"><b>Authorized credential</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><code>'+esc(p)+'</code></div></div>')}catch(err){toast(err.message||"Reveal rejected")}}
function merchantAccountCollection(uid,aid){var u=db.users.find(function(x){return x.id===uid}),a=(u?.upiAccounts||[]).find(function(x){return x.id===aid});if(!u||!a)return;if(a.merchantOperational===false||a.status!=="active")return toast("UPI account is stopped");modal('<div class="modalBox small"><div class="modalHead"><b>Add Collection · '+esc(a.label)+'</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="notice">Available '+money(accountCalc(u,a).available)+'</div>'+field("Bank Name","cBank","")+field("Account Number","cAccount","")+field("Amount INR","cAmount","","number")+field("Date","cDate",today(),"date")+field("Note","cNote","")+'</div><div class="modalFoot"><button class="btn primary" onclick="SF.saveAccountCollection(\''+uid+'\',\''+aid+'\')">Save</button></div></div>')}
async function saveAccountCollection(uid,aid){var u=db.users.find(function(x){return x.id===uid}),a=(u?.upiAccounts||[]).find(function(x){return x.id===aid});var amount=Number(v("cAmount")||0);if(!u||!a||amount<=0)return toast("Enter a valid amount");try{await backend.shareAction(location.hash.split("=").slice(1).join("="),{action:"collection",provider_id:u.remoteId,upi_account_id:aid,amount_inr:amount,bank_name:v("cBank"),account_number:v("cAccount"),transaction_date:v("cDate"),note:v("cNote"),idempotency_key:id("collection")});close();var r=await backend.resolveShare(location.hash.split("=").slice(1).join("="));db=r.state;render();toast("Collection added") }catch(err){toast(err.message||"Collection failed")}}
function publicNav(role,key){var root=document.querySelector(".readonly"),u=db.users&&db.users[0];if(!root||!u)return;root.querySelectorAll("[data-public-page]").forEach(function(x){x.style.display=x.dataset.publicPage===key?"":"none"})}
function publicUserPage(key){var u=db.users&&db.users[0];if(!u)return;var accounts=u.upiAccounts||[],body=key==="accounts"?'<div class="cardActions"><button class="btn primary" onclick="SF.addPublicUpi()">Add UPI Account</button></div>'+accounts.map(function(a){return accountRow(u,a,'<button class="btn ghost sm" onclick="SF.publicUpiCredentials(\''+a.id+'\')">GPay Details</button>')}).join(""):(key==="withdraw"&&u.fundingMode==="commission"?'<div class="detailKpis">'+metric("Total Earned",money(calc(u).commissionEarned))+metric("Available",money(calc(u).commissionEarned))+metric("Rate",money(107)+" / USDT")+'</div>'+field("USDT Amount","userWithdrawAmount","","number")+field("TRC20 Address","userWithdrawAddress","")+ '<button class="btn primary" onclick="SF.requestPublicWithdrawal(\'user\')">Submit Withdrawal</button>':key==="history"?((db.entries||[]).map(function(e){var a=accounts.find(function(x){return x.id===e.accountId});return entryRow({...e,note:(a?.label||"Legacy / Unassigned")+" · "+(e.note||"")},false)}).join("")||'<div class="empty">No history</div>'):accounts.map(function(a){return accountRow(u,a,'')}).join("")||'<div class="empty">No UPI accounts</div>');var p=document.querySelector('[data-public-page="content"]');if(p)p.innerHTML='<h2>'+({dashboard:"Dashboard",accounts:"My UPI Accounts",withdraw:"Withdraw Commission",history:"History"}[key]||"Dashboard")+'</h2>'+body}
function addPublicUpi(){var u=db.users&&db.users[0];if(u)addUpi(u.id)}
function publicUpiCredentials(aid){var u=db.users&&db.users[0];if(u)upiCredentials(u.remoteId,aid)}
function sharedDashboard(tokn,role){currentSharedRole=role;var expected=role==="Agent"?db.settings.agentToken:db.settings.merchantToken;if(tokn!==expected)return invalid(role+" link is invalid or revoked.");var accounts=allAccounts(),visible=accounts.filter(function(x){return x.u.status!=="deleted"&&x.u.active!==false});document.getElementById("app").innerHTML='<div class="readonly"><div class="readHead"><div class="logo"><div class="logoMark">◆</div><div>'+role+' Live Dashboard<div class="muted">Operational UPI accounts</div></div></div><span class="badge green">● Live</span></div><div class="panelNav">'+["dashboard","accounts","collections","settlement","withdrawals","charges","gpay","history"].map(function(k){return '<button class="btn ghost sm" onclick="SF.publicMerchantPage(\''+k+'\')">'+k+'</button>'}).join("")+'</div><section data-public-page="content"></section></div>';window.SF.publicMerchantPage=function(k){var c=k==="dashboard"?'<div class="detailKpis">'+metric("Total Collection",money(totals().collection))+metric("Available Limit",money(totals().capacity))+metric("Accounts",visible.length)+'</div>':k==="collections"?visible.map(function(x){return accountRow(x.u,x.a,'<button class="btn primary sm" onclick="SF.merchantAccountCollection(\''+x.u.id+'\',\''+x.a.id+'\')">Add Collection</button>')}).join(""):k==="settlement"?'<div class="detailKpis">'+metric("Total Collection",money(totals().collection))+metric("Available Settlement",money(Math.max(0,totals().collection-totals().frozen-totals().merchantSettled)))+'</div>':k==="charges"?((db.merchantCharges||[]).map(function(x){return '<div class="listRow"><b>'+money(x.amountInr)+'</b><span>'+esc(x.userName)+' · '+esc(x.upiId||"")+'</span></div>'}).join("")||'<div class="empty">No charges</div>'):visible.map(function(x){return accountRow(x.u,x.a,'')}).join("");var p=document.querySelector('[data-public-page="content"]');if(p)p.innerHTML='<h2>'+k+'</h2>'+c};window.SF.publicMerchantPage("dashboard")}
function userView(tokn){currentSharedRole="User";var u=db.users&&db.users[0];if(!u||u.token!==tokn||u.status==="deleted"||u.active===false)return invalid("User link is invalid or revoked.");document.getElementById("app").innerHTML='<div class="readonly"><div class="readHead"><div class="logo"><div class="logoMark">◆</div><div>'+esc(u.name)+'<div class="muted">'+esc(u.id)+'</div></div></div><span class="badge green">● Live</span></div><div class="panelNav">'+[["dashboard","Dashboard"],["accounts","My UPI Accounts"],["withdraw","Withdraw Commission"],["history","History"]].map(function(x){return '<button class="btn ghost sm" onclick="SF.publicUserPage(\''+x[0]+'\')">'+x[1]+'</button>'}).join("")+'</div><section data-public-page="content"></section></div>';window.SF.publicUserPage=publicUserPage;window.SF.addPublicUpi=addPublicUpi;window.SF.publicUpiCredentials=publicUpiCredentials;publicUserPage("dashboard")}
function nav(name,b){if(staffRole!=="admin")return;if(name==="settings")return settings();adminPage(name==="dashboard"?"dashboard":name);document.querySelectorAll(".nav button").forEach(function(x){x.classList.remove("active")});if(b)b.classList.add("active");var t=document.getElementById("title");if(t)t.textContent=name}
function admin(){if(!isAdminLoggedIn())return loginScreen();document.getElementById("app").innerHTML='<div class="shell"><aside class="side"><div class="logo"><div class="logoMark">◆</div><div>SettleFlow<div class="muted">GPay Control Center</div></div></div><div class="nav">'+[["dashboard","Dashboard"],["users","Users"],["accounts","UPI Accounts"],["ledger","Collections"],["commission","User Commission"],["userWithdrawals","User Withdrawals"],["merchantSettlement","Merchant Settlement"],["merchantWithdrawals","Merchant Withdrawals"],["charges","Charges"],["deposits","Deposits"],["frozen","Frozen"],["share","Share Links"],["gpay","GPay / QR"],["history","History / Audit"],["settings","Settings"]].map(function(x){return '<button onclick="SF.nav(\''+x[0]+'\',this)">'+x[1]+'</button>'}).join("")+'</div></aside><main class="main"><div class="top"><div><h1 id="title">Dashboard</h1><div class="muted">Production operations</div></div><button class="btn ghost" onclick="SF.logout()">Logout</button></div></main></div>';adminPage("dashboard")}
